const r = items[0].json;
if (!r.ok) {
  throw new Error(r.error || 'Report generation failed');
}
const s = r.summary || {};
const urls = r.download_urls || {};
const subject = `Delhivery Daily Report ${s.report_date || ''} — alarms ${s.alarm_count || 0} (active ${s.active_count || 0})`;
const html = `
<div style="font-family:Arial,sans-serif;max-width:720px">
  <h2 style="margin:0 0 8px">Delhivery — Daily Alarm & Telemetry Report</h2>
  <p style="color:#64748b;margin:0 0 16px">${s.window || ''}</p>
  <table style="border-collapse:collapse;width:100%;margin-bottom:16px">
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Total alarms</td><td style="padding:8px;border:1px solid #e2e8f0"><b>${s.alarm_count ?? 0}</b></td></tr>
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Active</td><td style="padding:8px;border:1px solid #e2e8f0"><b>${s.active_count ?? 0}</b></td></tr>
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Critical</td><td style="padding:8px;border:1px solid #e2e8f0"><b>${s.critical_count ?? 0}</b></td></tr>
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Major</td><td style="padding:8px;border:1px solid #e2e8f0"><b>${s.major_count ?? 0}</b></td></tr>
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Devices</td><td style="padding:8px;border:1px solid #e2e8f0">${(s.devices||[]).join(', ')}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e2e8f0">Telemetry points</td><td style="padding:8px;border:1px solid #e2e8f0">${s.telemetry_points ?? 0}</td></tr>
  </table>
  <p>Attachments: <b>report.pdf</b>, <b>alarms.csv</b>, <b>telemetry_latest.csv</b></p>
  <p style="color:#94a3b8;font-size:12px">Dashboard: https://viot.virtuosonetsoft.com/dashboards/c7229d20-812a-11f1-a760-b3ba4cbe1b98</p>
</div>`;
return [{
  json: {
    ...r,
    subject,
    html,
    fromEmail: 'information@variphi.com',
    toEmail: 'delhivery@virtuosonetsoft.com, information@variphi.com',
    pdfUrl: urls.pdf,
    alarmsCsvUrl: urls.alarms_csv,
    telemetryCsvUrl: urls.telemetry_csv,
  }
}];

const meta = $('Format email HTML').first().json;
const pdfBin = $('Download PDF').first().binary || {};
const alarmsBin = $('Download alarms CSV').first().binary || {};
const telemBin = $('Download telemetry CSV').first().binary || {};

const binary = {};
if (pdfBin.pdf) {
  binary.pdf = { ...pdfBin.pdf, fileName: `delhivery-report-${meta.report_date}.pdf`, mimeType: 'application/pdf' };
}
if (alarmsBin.alarms_csv) {
  binary.alarms_csv = { ...alarmsBin.alarms_csv, fileName: `delhivery-alarms-${meta.report_date}.csv`, mimeType: 'text/csv' };
}
if (telemBin.telemetry_csv) {
  binary.telemetry_csv = { ...telemBin.telemetry_csv, fileName: `delhivery-telemetry-${meta.report_date}.csv`, mimeType: 'text/csv' };
}

return [{
  json: {
    subject: meta.subject,
    html: meta.html,
    fromEmail: meta.fromEmail,
    toEmail: meta.toEmail,
    report_date: meta.report_date,
    summary: meta.summary,
  },
  binary,
}];
